int online_memory_range(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct mem_notify {
        int status;
        int nid;
    } notify;

    lock_memory_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        notify.nid = pfn_to_nid(pfn);
        send_notification(&notify, MEM_GOING_ONLINE);
        if (notify.status < 0) {
            ret = notify.status;
            goto unlock_exit;
        }
    }

    if (!zone_populated(current_zone)) {
        rebuild_zonelists();
    }

    if (online_pages(pfn, nr_pages)) {
        update_zone_statistics(pfn, nr_pages);
        trigger_zonelist_rebuild();
        send_notification(&notify, MEM_ONLINE);
    } else {
        ret = -EINVAL;
        goto unlock_exit;
    }

unlock_exit:
    unlock_memory_hotplug();
    return ret;
}

int online_pages(unsigned long pfn, unsigned long nr_pages) {
    int ret = 0;
    struct memory_notify notify = { 0 };

    lock_hotplug();

    if (!node_online(pfn_to_nid(pfn))) {
        notify.status_change = MEM_ONLINE;
        notify.start_pfn = pfn;
        notify.end_pfn = pfn + nr_pages;
        notify.new_node_id = NUMA_NO_NODE;
        ret = send_memory_notify(NOTIFY_STATUS_CHANGE, &notify, NULL);
        if (ret < 0)
            goto out;
    }

    if (zone_is_populated(pfn_to_zone(pfn))) {
        rebuild_zonelist();
        update_zone_statistics();
    }

    ret = online_page_range(pfn, nr_pages);
    if (ret < 0)
        goto out;

    notify.status_change = MEM_ONLINE;
    notify.start_pfn = pfn;
    notify.end_pfn = pfn + nr_pages;
    send_memory_notify(NOTIFY_ONLINE, &notify, NULL);

out:
    unlock_hotplug();
    return ret;
}
